#!/usr/bin/env python3
"""Generate one prompt file for EACH required asset from the locked single-source brand.
No images are generated by this utility.
"""
import argparse,json,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
GUIDANCE={
 '01': 'CINEMATIC PANORAMA. Main hero horizontal panoramic banner. Fully niche-specific scene, premium lighting and central brand lockup. Do not crop a 16:9 scene into this format. Put primary artwork and title comfortably in the central strip.',
 '02': 'STORY SCENE A. Niche-specific 16:9 editorial illustration showing a complete event/process/battle; staged with left/right or other niche-correct action flow. Different composition from 01 and 06. This is a standalone rendered image, not a collage preview.',
 '03': 'HORIZONTAL LOGO + NAME. Emblem on left plus exact brand name on right; descriptor optional. REAL TRANSPARENT alpha background, no black/white flat backdrop, no checkerboard baked into pixels. Keep generous spacing and readable branding.',
 '04': 'CIRCULAR AVATAR. Distinctive original emblem centered inside circle, attractive even at 98x98. Opaque brand / white / transparent outside circle all permitted. Avoid tiny text; if full name illegible, use brand monogram.',
 '05': 'WORDMARK-ONLY. Typography-first brand name, no large separate emblem, horizontal composition. REAL TRANSPARENT PNG alpha background. Match exact word spelling, case and brand palette.',
 '06': 'STORY SCENE B. NEW standalone 16:9 key scene, not a crop/resize of Scene A: alter event, background, camera angle, foreground placement and action. Preserve same recognizable brand DNA.',
}
def main():
 ap=argparse.ArgumentParser()
 ap.add_argument('--brand',required=True)
 ap.add_argument('--profile',choices=['reference6','legacy5'],default='reference6')
 ap.add_argument('--out',required=True,help='Markdown summary file to create')
 ap.add_argument('--allow-draft',action='store_true',help='Only for brainstorming; do not release renders as final')
 args=ap.parse_args()
 b=json.loads(pathlib.Path(args.brand).read_text(encoding='utf-8'))
 if not str(b.get('brand_name','')).strip():ap.error('brand_name is required')
 lock=str(b.get('lock_status',b.get('status',''))).upper()
 if not args.allow_draft and lock not in ('LOCKED','DEMO_LOCKED'):
  ap.error('brand.lock.json must have lock_status=LOCKED; use --allow-draft only for preliminary prompts')
 spec=json.loads((ROOT/'templates'/('asset_spec_reference6.json' if args.profile=='reference6' else 'asset_spec.json')).read_text(encoding='utf-8'))
 if b.get('asset_profile') and b['asset_profile'].upper().replace('_','')!=args.profile.upper().replace('_',''):
  ap.error('Profile does not match asset_profile in brand.lock.json')
 title=b['brand_name']; tagline=b.get('tagline',''); descriptor=b.get('descriptor','')
 style=b.get('style','AUTO'); niche=b.get('niche',''); motif=b.get('logo_motif','');palette=b.get('palette',{})
 locale=b.get('locale', 'en'); content_format=b.get('content_format','LONG_FORM'); scope=b.get('niche','')
 extra=''
 if str(locale).lower().startswith('es'):extra+='All visible taglines, descriptive text and SEO must remain Spanish; maintain all Unicode accents. '
 if 'boss' in (str(niche)+' '+str(b.get('scope',''))).lower():extra+='ONE hero squad vs ONE prominently giant boss, not two balanced teams. '
 if b.get('fan_project'):extra+='Unofficial fan project, avoid implying official publisher affiliation. '
 rules=f'''LOCKED BRAND CANON. LOCALE={locale!r}, CONTENT_FORMAT={content_format!r}. {extra}No Shorts or meme framing when content_format=LONG_FORM. NEVER copy another channel's name or other assets. Exact name: {title!r}. Exact descriptor: {descriptor!r}. Exact tagline: {tagline!r}. Niche: {niche!r}. Style: {style!r}. Palette: {json.dumps(palette,ensure_ascii=False)}. Emblem motif: {motif!r}. NEVER substitute a different niche, brand name, mascot or palette. Canvas is defined below; text in raster renders may be imperfect, so prefer GENERATE BACKGROUND WITHOUT TEXT → COMPOSITE BRAND TYPE EXACTLY using real text. Do not use any unrelated sample brand artwork. No extra subscribe/YouTube glyphs unless authorized.'''
 out=pathlib.Path(args.out)
 out.parent.mkdir(parents=True,exist_ok=True)
 prompt_dir=out.parent/'prompts';prompt_dir.mkdir(parents=True,exist_ok=True)
 chunks=[f'# Prompt pack: {title}',f'PROFILE={args.profile.upper()} | Main files={len(spec["required_assets"])} | Status={lock}', '',rules,'']
 for item in spec['required_assets']:
  key=item['id'];s=f"{key} {item['filename']} ({item['width']}x{item['height']} {item['format']})"
  req=GUIDANCE[key] if args.profile=='reference6' else GUIDANCE.get(key,'Same brand; independent composition.')
  instr=f'''# ASSET {s}\n{rules}\nOUTPUT FILE: {item['filename']}\nREQUIRED EXACT DIMENSIONS: {item['width']}×{item['height']} px. FORMAT: {item['format']}.\nROLE: {req}\nTransparent PNG required: {'YES - real alpha, at least 2% fully transparent' if item.get('alpha_required') else 'NO, optional for avatar' if key=='04' else 'NO'}.\nDo not resize a different canvas and do not reuse a contact sheet crop as final. The frame must be intentionally composed for this exact shape.\n'''
  (prompt_dir/(key+'_asset_prompt.md')).write_text(instr,encoding='utf-8')
  chunks+=['## '+s,req,'']
 for item in spec['upload_assets']:
  chunks+=['## YouTube upload-ready bonus',f"Output {item['filename']}, exactly {item['width']}×{item['height']} {item['format']} up to 6MiB. Recompose from original scene; keep all primary text/emblem within safe area bbox {spec['safe_area_youtube_px']['bbox_center']}; verify visually. Do not stretch the 3:1 panoramic image.",'']
 out.write_text('\n'.join(chunks)+'\n',encoding='utf-8')
 print(json.dumps({'status':'PROMPTS_ONLY','prompt_files':len(spec['required_assets']),'profile':args.profile,'output':str(out)},ensure_ascii=False))
if __name__=='__main__':main()
